// full pathway card for one entry
export function refCard([name, tier, tpl]) {
  const t = REF_T[tpl];
  return `${name.toUpperCase()}  [DIFFICULTY ${tier}/5]\nEXAM: ${t.exam}\nWORKUP: ${t.dx}\nSTABILIZE: ${t.stab}\nDISPO: ${t.dispo}`;
}

// keyword search over the index — returns best-matching entries
export function lookupRef(query, limit = 3) {
  const q = ` ${String(query).toLowerCase().replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim()} `;
  const words = q.trim().split(' ').filter((w) => w.length >= 3);
  if (!words.length) return [];
  const scored = [];
  for (const e of REF) {
    const name = ` ${e[0].toLowerCase()} `;
    let score = 0;
    if (q.includes(name.trim())) score += 10; // exact name inside the query
    for (const w of words) {
      if (name.includes(` ${w}`)) score += 2;
      else if (name.includes(w)) score += 1;
    }
    if (score > 0) scored.push([score, e]);
  }
  scored.sort((a, b) => b[0] - a[0]);
  return scored.slice(0, limit).map(([, e]) => e);
}
